// ───────────────────────────────────────────────────────────
// LLM Error Handler
// Fires when AI Summarizer fails (both Local LLM and
// OpenRouter Fallback are unreachable / error out).
// Pulls context from Build Prompt and routes to Format Error
// so the existing error → Mark URL Processed → Send to Slack
// pipeline handles it cleanly.
// ───────────────────────────────────────────────────────────

let buildData = {};
try {
  buildData = $('Build Prompt').first().json;
} catch (e) {
  // Build Prompt might not be reachable if the failure is very early
}

const url = buildData.url || $json.url || '';
const language = buildData.language || $json.language || 'en';
const slack_channel = buildData.slack_channel || $json.slack_channel || '';
const slack_ts = buildData.slack_ts || $json.slack_ts || '';
const slack_thread_ts = buildData.slack_thread_ts || $json.slack_thread_ts || null;

// Extract the most useful error message from whatever n8n gives us
const errMsg = $json.error?.message
  || $json.error
  || $json.message
  || $json.errorMessage
  || 'Both Local LLM and OpenRouter fallback failed';

return [{ json: {
  error: `LLM failure: ${errMsg}`,
  url,
  language,
  slack_channel,
  slack_ts,
  slack_thread_ts
}}];

const body = $json.body || $json;
const event = body.event || {};
const headers = $json.headers || {};

if (headers['x-slack-retry-num']) return [];

const BOT_USER_ID = 'U07K8QJ9XYZ';

if (event.subtype === 'message_changed') {
  const prev = event.previous_message?.text || '';
  const curr = event.message?.text || '';
  if (prev === curr) return [];

  const extractUrls = (text) => {
    const urls = new Set();
    const slackRx = /<(https?:\/\/[^>|]+)(\|[^>]+)?>/g;
    let m;
    while ((m = slackRx.exec(text)) !== null) urls.add(m[1]);
    const plainRx = /https?:\/\/[^\s<>"'\[\]{}|]+/g;
    while ((m = plainRx.exec(text)) !== null) urls.add(m[0].replace(/[.,;:)]+$/, ''));
    return urls;
  };

  const prevUrls = extractUrls(prev);
  const currUrls = extractUrls(curr);
  const newUrls = [...currUrls].map(u => u.split('|')[0]).filter(u => !prevUrls.has(u) && u.match(/^https?:\/\/.+\..+/));

  if (newUrls.length === 0) return [];

  const user = event.message?.user || event.previous_message?.user || '';
  if (!user || user === BOT_USER_ID || event.message?.bot_id) return [];

  const staticData = $getWorkflowStaticData('global');
  if (!staticData.processedUrls) staticData.processedUrls = {};
  if (!staticData.processedMsgs) staticData.processedMsgs = {};

  const msgKey = `${user}_${event.message?.ts || event.ts}_edited`;
  if (staticData.processedMsgs[msgKey]) return [];
  staticData.processedMsgs[msgKey] = Date.now();

  const twoDaysAgo = Date.now() - 172800000;
  for (const k of Object.keys(staticData.processedUrls)) if (staticData.processedUrls[k] < twoDaysAgo) delete staticData.processedUrls[k];
  for (const k of Object.keys(staticData.processedMsgs)) if (staticData.processedMsgs[k] < twoDaysAgo) delete staticData.processedMsgs[k];

  const results = [];
  const fourHoursAgo = Date.now() - 14400000;
  for (const url of newUrls) {
    const isDuplicate = staticData.processedUrls[url] > fourHoursAgo;
    if (!isDuplicate) staticData.processedUrls[url] = Date.now();
    const slack_ts = event.message?.ts || event.ts;
    const slack_thread_ts = event.message?.thread_ts || null;
    results.push({ json: { isDuplicate, url, slack_channel: event.channel, slack_user: user, slack_ts, slack_thread_ts } });
  }
  return results;
}

const skipSubtypes = ['bot_message','message_deleted','channel_join','channel_leave','channel_topic','channel_purpose','file_share','pinned_item','unpinned_item'];
if (event.subtype && skipSubtypes.includes(event.subtype)) return [];
if (event.type !== 'message' || event.bot_id || event.user === BOT_USER_ID || !event.text) return [];

const text = event.text || '';
const urls = new Set();
const slackRx = /<(https?:\/\/[^>|]+)(\|[^>]+)?>/g;
let m;
while ((m = slackRx.exec(text)) !== null) urls.add(m[1]);
const plainRx = /https?:\/\/[^\s<>"'\[\]{}|]+/g;
while ((m = plainRx.exec(text)) !== null) urls.add(m[0].replace(/[.,;:)]+$/, ''));

const validUrls = [...urls].map(u => u.split('|')[0]).filter(u => u.match(/^https?:\/\/.+\..+/));
if (validUrls.length === 0) return [];

const staticData = $getWorkflowStaticData('global');
if (!staticData.processedUrls) staticData.processedUrls = {};
if (!staticData.processedMsgs) staticData.processedMsgs = {};

const msgKey = `${event.user}_${event.ts}`;
if (staticData.processedMsgs[msgKey]) return [];
staticData.processedMsgs[msgKey] = Date.now();

const fourHoursAgo = Date.now() - 14400000;
const twoDaysAgo = Date.now() - 172800000;
for (const k of Object.keys(staticData.processedUrls)) if (staticData.processedUrls[k] < twoDaysAgo) delete staticData.processedUrls[k];
for (const k of Object.keys(staticData.processedMsgs)) if (staticData.processedMsgs[k] < twoDaysAgo) delete staticData.processedMsgs[k];

const results = [];
for (const url of validUrls) {
  const isDuplicate = staticData.processedUrls[url] > fourHoursAgo;
  if (!isDuplicate) staticData.processedUrls[url] = Date.now();
  const slack_ts = event.ts;
  const slack_thread_ts = event.thread_ts || null;
  results.push({ json: { isDuplicate, url, slack_channel: event.channel, slack_user: event.user, slack_ts, slack_thread_ts } });
}
return results;

// ───────────────────────────────────────────────────────────
// Extract Text (multi-strategy, length-aware)
// FIX: previously the first strategy returning >300 chars won, so a
// truncated result (e.g. only the first <div> paragraph) was accepted.
// Now strategies are tried in priority order and one is only accepted
// if it is "good" (>= MIN_GOOD chars). Thin results are kept as a
// fallback and the workflow escalates to Jina; the longer text wins.
// ───────────────────────────────────────────────────────────
const headers = $json.headers || {};
const contentType = (headers['content-type'] || headers['Content-Type'] || '').toLowerCase();
let ctx = {};
try { ctx = $('Is Duplicate?').first().json || {}; } catch (e) {}
const url = $json.url || ctx.url || '';
const slack_channel = $json.slack_channel || ctx.slack_channel || '';
const slack_ts = $json.slack_ts || ctx.slack_ts || '';
const slack_thread_ts = $json.slack_thread_ts || ctx.slack_thread_ts || null;

const MIN_OK = 200;     // below this: extraction failed outright
const MIN_GOOD = 1500;  // below this: suspicious (probably truncated) -> try Jina too
const MAX_LEN = 12000;

const decodeEntities = (str) => str
  .replace(/&quot;/g, '"').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&#39;/g, "'").replace(/&apos;/g, "'").replace(/&#x27;/g, "'")
  .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)));

// Routed here from an upstream "needs Jina" flag -> pass straight through
if ($json.needsJina) {
  return [{ json: { needsJina: true, url, slack_channel, slack_ts, slack_thread_ts, error: $json.error || 'Direct fetch blocked' } }];
}

if (contentType && !contentType.includes('text/html') && !contentType.includes('application/xhtml') && !contentType.includes('text/plain')) {
  return [{ json: { error: `Non-HTML content (${contentType.split(';')[0]}). Cannot extract article text.`, url, slack_channel, slack_ts, slack_thread_ts, needsJina: false } }];
}

const rawHtml = $json.body || $json.data || $json.html || $json.content || '';
const html = typeof rawHtml === 'string' ? rawHtml : '';
if (!html || html.length < 100) {
  return [{ json: { error: 'No HTML content received', url, slack_channel, slack_ts, slack_thread_ts, needsJina: true } }];
}

// ── Noise removal ──
const stripNoise = (h) => h
  .replace(/<figcaption[\s\S]*?<\/figcaption>/gi, '')
  .replace(/<figure[\s\S]*?<\/figure>/gi, '')
  .replace(/<div[^>]*class="[^"]*(?:caption|credit|photo-credit|image-credit|img-credit|media-credit|photographer|תמונה|צילום)[^"]*"[^>]*>[\s\S]*?<\/div>/gi, '')
  .replace(/<span[^>]*class="[^"]*(?:caption|credit|photo-credit|image-credit|photographer|תמונה|צילום)[^"]*"[^>]*>[\s\S]*?<\/span>/gi, '')
  .replace(/<p[^>]*class="[^"]*(?:caption|credit|photo-credit|image-credit|photographer|צילום)[^"]*"[^>]*>[\s\S]*?<\/p>/gi, '')
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<nav[\s\S]*?<\/nav>/gi, '')
  .replace(/<aside[\s\S]*?<\/aside>/gi, '')
  .replace(/<footer[\s\S]*?<\/footer>/gi, '');

// HTML -> plain text (keeps block boundaries as spaces)
const toText = (h) => stripNoise(h)
  .replace(/<br\s*\/?>/gi, ' ')
  .replace(/<\/(?:p|div|li|h[1-6]|blockquote)>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

// Photo-credit cleanup. Only strips unambiguous credit patterns
// (the old version could eat up to 120 chars of body text at end-of-string).
const stripCaptionText = (t) => t
  .replace(/צילום[י]?\s*[:\/|]?\s*[^.;\n]{0,120}סעיף\s*\d+[א-ת]?'?/g, '')
  .replace(/\(\s*צילום[י]?\s*[:\/|][^)]{0,80}\)/g, '')
  .replace(/(?:תמונת?\s*(?:ארכיון|אילוסטרציה)|צילום\s*אילוסטרציה)[^.;\n]{0,60}/g, '')
  .replace(/(?:photo|image|illustration)\s*(?:credit|by|courtesy|via)\s*[:.]?\s*[^.;\n]{0,100}/gi, '')
  .replace(/(?:^|\n)\s*(?:credit|source|photo)\s*:\s*[^\n]{0,100}/gi, '');

// Returns the full balanced <div>…</div> that starts at startIdx
// (the old non-greedy regex stopped at the FIRST </div> = first paragraph).
const balancedDiv = (src, startIdx) => {
  const re = /<(\/?)div\b[^>]*>/gi;
  re.lastIndex = startIdx;
  let depth = 0, m;
  while ((m = re.exec(src)) !== null) {
    if (m[1] === '') depth++;
    else { depth--; if (depth === 0) return src.slice(startIdx, re.lastIndex); }
  }
  return src.slice(startIdx);
};

const longestOf = (arr) => arr.reduce((a, b) => (b.length > a.length ? b : a), '');

// ── Page metadata (title / author / date / site) ──
// The body extractors above only keep the article text, so the byline and
// publication date (which live in the page header) were never reaching the Q&A agent.
const metaContent = (names) => {
  for (const n of names) {
    const key = n.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const a = html.match(new RegExp(`<meta[^>]+(?:name|property)=["']${key}["'][^>]*?content=["']([^"']*)["']`, 'i'));
    const b = html.match(new RegExp(`<meta[^>]+content=["']([^"']*)["'][^>]*?(?:name|property)=["']${key}["']`, 'i'));
    const v = ((a && a[1]) || (b && b[1]) || '').trim();
    if (v) return decodeEntities(v);
  }
  return '';
};

const ldMeta = () => {
  const out = { author: '', published: '', headline: '' };
  const authorName = (a) => {
    if (!a) return '';
    if (typeof a === 'string') return a;
    if (Array.isArray(a)) return a.map(authorName).filter(Boolean).join(', ');
    return a.name || '';
  };
  const visit = (o) => {
    if (!o) return;
    if (Array.isArray(o)) { o.forEach(visit); return; }
    if (typeof o === 'object') {
      if (!out.author && o.author) out.author = authorName(o.author);
      if (!out.published && o.datePublished) out.published = String(o.datePublished);
      if (!out.headline && o.headline) out.headline = String(o.headline);
      if (o['@graph']) visit(o['@graph']);
    }
  };
  const rx = /<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
  let m;
  while ((m = rx.exec(html)) !== null) { try { visit(JSON.parse(m[1])); } catch (e) {} }
  return out;
};

// Person byline links such as <a href="/writer/2444">Name</a> (walla, many others)
const anchorAuthor = () => {
  const m = html.match(/<a[^>]+href=["'][^"']*(?:\/writer\/|\/author\/|\/authors\/|\/byline\/|\/reporter\/|\/journalist\/)[^"']*["'][^>]*>([\s\S]*?)<\/a>/i)
         || html.match(/<a[^>]+rel=["']author["'][^>]*>([\s\S]*?)<\/a>/i);
  const t = m ? toText(m[1]) : '';
  return t.length >= 2 && t.length <= 60 ? t : '';
};

const ld = ldMeta();
const authorTag = metaContent(['author', 'article:author', 'vr:author', 'og:article:author', 'parsely-author', 'dc.creator', 'sailthru.author', 'twitter:creator']);
const meta = {
  title: metaContent(['og:title', 'twitter:title']) || ld.headline || ((html.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1] || ''),
  author: anchorAuthor() || (/^https?:/i.test(authorTag) ? '' : authorTag) || ld.author,
  published: metaContent(['article:published_time', 'og:published_time', 'vr:published_time', 'datePublished', 'date']) || ld.published || ((html.match(/<time[^>]+datetime=["']([^"']+)["']/i) || [])[1] || ''),
  site: metaContent(['og:site_name']),
  description: metaContent(['og:description', 'description', 'twitter:description'])
};
for (const k of Object.keys(meta)) meta[k] = decodeEntities(String(meta[k] || '')).replace(/\s+/g, ' ').trim().slice(0, 400);

// ── Strategies (priority order) ──
const getLd = () => {
  let best = '';
  const visit = (o) => {
    if (!o) return;
    if (Array.isArray(o)) { o.forEach(visit); return; }
    if (typeof o === 'object') {
      if (typeof o.articleBody === 'string' && o.articleBody.length > best.length) best = o.articleBody;
      if (o['@graph']) visit(o['@graph']);
    }
  };
  const rx = /<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
  let m;
  while ((m = rx.exec(html)) !== null) { try { visit(JSON.parse(m[1])); } catch (e) {} }
  return best.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
};

const getBodyDiv = () => {
  const rx = /<div[^>]*class="[^"]*(?:art_body|article_text|article-body|article__body|post-content|entry-content|story-body|article__content|content-body)[^"]*"[^>]*>/gi;
  const found = [];
  let m;
  while ((m = rx.exec(html)) !== null) found.push(toText(balancedDiv(html, m.index)));
  return longestOf(found);
};

const getParas = () => {
  const seen = new Set();
  const out = [];
  const push = (raw) => {
    const t = toText(raw);
    if (t.length > 40 && !/cookie|privacy|subscribe|newsletter|הרשמה|פרטיות/i.test(t) && !seen.has(t)) { seen.add(t); out.push(t); }
  };
  for (const m of html.matchAll(/<p(?:\s[^>]*)?>([\s\S]*?)<\/p>/gi)) {
    if (!/class="[^"]*(?:caption|credit|photo|צילום)/i.test(m[0].slice(0, 200))) push(m[1]);
  }
  for (const m of html.matchAll(/<div[^>]*class="[^"]*text_editor_paragraph[^"]*"[^>]*>([\s\S]*?)<\/div>/gi)) push(m[1]);
  return out.length >= 3 ? out.join(' ') : '';
};

const getArticle = () => longestOf([...html.matchAll(/<article[^>]*>([\s\S]*?)<\/article>/gi)].map(m => toText(m[1])));
const getMain = () => longestOf([...html.matchAll(/<main[^>]*>([\s\S]*?)<\/main>/gi)].map(m => toText(m[1])));

const strategies = [['ldjson', getLd], ['bodyDiv', getBodyDiv], ['paragraphs', getParas], ['article', getArticle], ['main', getMain]];

let text = '', used = '';
let longest = '', longestName = '';
for (const [name, fn] of strategies) {
  let t = '';
  try { t = fn() || ''; } catch (e) {}
  if (t.length > longest.length) { longest = t; longestName = name; }
  if (t.length >= MIN_GOOD) { text = t; used = name; break; }
}
if (!text) { text = longest; used = longestName; }

// ── Final cleanup ──
text = text
  .replace(/all rights reserved|כל הזכויות שמורות|copyright \d{4}|©\s*\d{4}/gi, '')
  .replace(/follow us on.*|עקבו אחרינו.*/gi, '');
text = stripCaptionText(text).replace(/\s+/g, ' ').trim();
text = decodeEntities(text);

if (!text || text.length < MIN_OK) {
  return [{ json: { error: 'Direct extraction failed', meta, url, slack_channel, slack_ts, slack_thread_ts, needsJina: true } }];
}

if (text.length < MIN_GOOD) {
  // Suspiciously short: ask Jina too, keep this text as a fallback
  return [{ json: { needsJina: true, error: `Direct extraction thin (${text.length} chars via ${used})`, directArticle: text, meta, url, slack_channel, slack_ts, slack_thread_ts } }];
}

if (text.length > MAX_LEN) text = text.substring(0, MAX_LEN) + '... [truncated]';
// Language detection happens in the dedicated 'Detect Language' node.
return [{ json: { article: text, url, charCount: text.length, extractMethod: used, meta, needsJina: false, slack_channel, slack_ts, slack_thread_ts } }];

let raw = $json.output || $json.text || $json.content || '';
if (typeof raw !== 'string') raw = JSON.stringify(raw);

const bp = $('Build Prompt').first().json;
const url = bp.url || '';
const language = bp.language || 'en';
const slack_channel = bp.slack_channel || '';
const slack_ts = bp.slack_ts || '';
const slack_thread_ts = bp.slack_thread_ts || null;
const charCount = bp.charCount || 0;
const extractMethod = bp.extractMethod || '';

const decodeEntities = (str) => str
  .replace(/&quot;/g, '"').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&#39;/g, "'").replace(/&apos;/g, "'").replace(/&#x27;/g, "'")
  .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)));

try {
  const unwrapped = JSON.parse(raw);
  if (typeof unwrapped === 'string') raw = unwrapped;
} catch (e) {}

raw = raw.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();

let s = raw.replace(/```json\s*/gi, '').replace(/```\s*/g, '');

// Escape Hebrew acronym quotes
s = s.replace(/([\u0590-\u05FF])["״\u201C\u201D]([\u0590-\u05FF])/g, '$1\\"$2');

// Merge duplicate bullets keys
if ((s.match(/"bullets"\s*:/g) || []).length > 1) {
  const tm = s.match(/"title"\s*:\s*"((?:[^"\\]|\\.)*)"/);
  const allBullets = [];
  const bulletRx = /"bullets"\s*:\s*\[\s*"((?:[^"\\]|\\.)*)"\s*\]/g;
  let bm;
  while ((bm = bulletRx.exec(s)) !== null) allBullets.push(bm[1]);
  if (tm && allBullets.length > 1) s = JSON.stringify({ title: tm[1], bullets: allBullets });
}

const si = s.indexOf('{');
const ei = s.lastIndexOf('}');
if (si > -1 && ei > si) s = s.substring(si, ei + 1);

s = s.replace(/[\r\n]+/g, ' ').replace(/[\u2018\u2019]/g, "'").replace(/[\u201C\u201D]/g, '"').trim();

let title = 'Summary';
let bullets = [];

try {
  const obj = JSON.parse(s);
  title = obj.title || 'Summary';
  bullets = Array.isArray(obj.bullets) ? obj.bullets : [];
} catch (e) {
  try {
    let fixed = s.replace(/,\s*]/g, ']').replace(/,\s*}/g, '}');
    const obj = JSON.parse(fixed);
    title = obj.title || 'Summary';
    bullets = Array.isArray(obj.bullets) ? obj.bullets : [];
  } catch (e2) {
    try {
      let repair = s;
      const openBrackets = (repair.match(/\[/g) || []).length;
      const closeBrackets = (repair.match(/\]/g) || []).length;
      const openBraces = (repair.match(/\{/g) || []).length;
      const closeBraces = (repair.match(/\}/g) || []).length;
      const quotes = repair.match(/(?<!\\)"/g) || [];
      if (quotes.length % 2 !== 0) repair += '"';
      for (let i = 0; i < (openBrackets - closeBrackets); i++) repair += ']';
      for (let i = 0; i < (openBraces - closeBraces); i++) repair += '}';
      repair = repair.replace(/,\s*]/g, ']').replace(/,\s*}/g, '}');
      const obj = JSON.parse(repair);
      title = obj.title || 'Summary';
      bullets = Array.isArray(obj.bullets) ? obj.bullets : [];
    } catch (e3) {
      try {
        const tm = s.match(/"title"\s*:\s*"((?:[^"\\]|\\.)*)"/);
        if (tm) title = tm[1].replace(/\\"/g, '"').replace(/\\n/g, ' ');
        const bulletsStart = s.indexOf('"bullets"');
        if (bulletsStart > -1) {
          const afterBullets = s.substring(bulletsStart);
          const bracketStart = afterBullets.indexOf('[');
          if (bracketStart > -1) {
            const bulletsContent = afterBullets.substring(bracketStart + 1);
            const completeStrings = [];
            let inString = false;
            let current = '';
            let escaped = false;
            for (let i = 0; i < bulletsContent.length; i++) {
              const ch = bulletsContent[i];
              if (escaped) { current += ch; escaped = false; continue; }
              if (ch === '\\') { current += ch; escaped = true; continue; }
              if (ch === '"') {
                if (inString) {
                  if (current.length > 25) completeStrings.push(current.replace(/\\"/g, '"').replace(/\\n/g, ' '));
                  current = ''; inString = false;
                } else {
                  inString = false; current = ''; inString = true;
                }
              } else if (inString) current += ch;
            }
            if (completeStrings.length > 0) bullets = completeStrings;
          }
        }
      } catch (e4) {
        const tm = s.match(/"title"\s*:\s*"((?:[^"\\]|\\.)*)"/);
        const bm = s.match(/"bullets"\s*:\s*\[([\s\S]*?)\]/);
        if (tm) title = tm[1];
        if (bm) bullets = [...bm[1].matchAll(/"((?:[^"\\]|\\.){10,})"/g)].map(m => m[1]).filter(b => b.length > 15);
      }
    }
  }
}

title = decodeEntities(String(title));

bullets = bullets
  .map(b => {
    let cleaned = String(b)
      .replace(/^[•\-\s]+/, '')
      .replace(/\s*•\s*/g, ' ')
      .replace(/\.{2,}/g, '.')
      .replace(/\s+/g, ' ')
      .replace(/\\n/g, ' ')
      .replace(/\\"/g, '"')
      .trim();
    return decodeEntities(cleaned);
  })
  .filter(b => {
    if (!b || b.length < 25) return false;
    const lc = b.toLowerCase();
    return !lc.includes('no further details') && !lc.includes('no additional details') &&
           !lc.includes('לא נמצאו פרטים') && !lc.includes('אין פרטים') &&
           !lc.includes('информация недоступна');
  });

if (bullets.length === 0) {
  const noContent = { he: 'לא הצלחתי לחלץ מידע מהמאמר', ru: 'Не удалось извлечь информацию', en: 'Could not extract summary from article' };
  return [{ json: { text: `⚠️ ${noContent[language] || noContent.en}`, url, language, charCount, extractMethod, bulletCount: 0, slack_channel, slack_ts, slack_thread_ts } }];
}

// ── Filler-sentence removal ──
// Split into sentences and drop only sentences that START with filler.
const FILLER_STARTS = [
  /^This\s+(strategic|operational|fiscal|historical|massive|directive|depletion|transition|situation|shift|outreach|move|decision|availability|technical|effort|release|step|approach|new\s+generation|latest\s+\w+)\s+\S+/i,
  /^This\s+\w+\s+(aims|seeks|intends|ensures|serves|supports|highlights|mirrors|positions|reflects|demonstrates|underscores|represents|illustrates|facilitates|creates|introduces|marks|signals|offers)\s+/i,
  /^Such\s+(a|an)\s+\S+\s+(would|will|serves|reflects|demonstrates|transforms|ensures)\s+/i,
  /^These\s+\S+\s+(ensure|ensures|serve|serves|support|supports|reflect|reflects)\s+/i,
  /^The\s+(company|article|report)\s+(continues|aims|seeks)\s+/i,
