}

// Pass through with context fields appended
return [{ json: { ...$json, url, slack_channel, slack_ts, slack_thread_ts } }];

// Permanent log entry for every processed link. 'Log Push' appends it to a Redis list per month
// (log:YYYY-MM); the weekly digest reads those lists.
const url = $json.url || '';
const text = $json.text || '';
const isError = text.startsWith('⚠️');
let domain = '';
try { domain = new URL(url).hostname.replace(/^www\./, ''); } catch (e) {}

const record = {
  type: 'summary',
  ts: new Date().toISOString(),
