return [{ json: { text: `${msgs[language] || msgs.en}\n${reasons[language] || reasons.en} ${err}`, url, language, charCount: 0, slack_channel, slack_ts, slack_thread_ts } }];

const raw = $json.data || $json.body || $json.content || '';
const prevData = $('Needs Jina Fallback?').first().json;
const url = prevData.url || '';
const slack_channel = prevData.slack_channel || '';
const slack_ts = prevData.slack_ts || '';
const slack_thread_ts = prevData.slack_thread_ts || null;
const directArticle = prevData.directArticle || '';   // thin-but-usable text from direct fetch

const MAX_LEN = 12000;

