text = text
  .replace(/צילום[י]?\s*[:\/|]?\s*[^.;\n]{0,120}סעיף\s*\d+[א-ת]?'?/g, '')
  .replace(/\(\s*צילום[י]?\s*[:\/|][^)]{0,80}\)/g, '')
  .replace(/(?:תמונת?\s*(?:ארכיון|אילוסטרציה)|צילום\s*אילוסטרציה)[^.;\n]{0,60}/g, '')
  .replace(/(?:photo|image|illustration)\s*(?:credit|by|courtesy|via)\s*[:.]?\s*[^.;\n]{0,100}/gi, '')
