const body = $json.body || $json;
const event = body.event || {};
const headers = $json.headers || {};

// ── config ──────────────────────────────────────────────────
const BOT_USER_ID = 'U07K8QJ9XYZ';  // fallback only – the real bot id is read from the event's "authorizations" when Slack sends it
const REQUIRE_MENTION = false;      // true = only answer thread messages when the bot is @mentioned
const MAX_QUESTION_CHARS = 1500;
// Slack emoji name -> action
const REACTIONS = {
  brain: 'quiz',
  zap: 'tldr',
  pushpin: 'save', round_pushpin: 'save', star: 'save',
  'flag-il': 'translate:he',
  'flag-us': 'translate:en', 'flag-gb': 'translate:en',
  'flag-ru': 'translate:ru'
};
