// ── shared quiz helpers (injected at build time into 'Prepare Question' and 'Build Quiz') ──
const RLM = '\u200F', LRM = '\u200E';
// Isolate Latin/number tokens as whole units (never split "5,000")
const wrapLatin = (t) => t.replace(/[A-Za-z0-9]+(?:[.,:\/\-][A-Za-z0-9]+)*/g, (tok) =>
  (/[A-Za-z]/.test(tok) || /[.,:\/\-]/.test(tok)) ? `${LRM}${tok}${LRM}` : tok);
const wrapOutsideUrls = (t) => t.split(/(https?:\/\/[^\s)>\]]+)/g).map((seg, i) => (i % 2 ? seg : wrapLatin(seg))).join('');
const esc = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const LETTERS = { he: ['א', 'ב', 'ג', 'ד'], en: ['A', 'B', 'C', 'D'], ru: ['A', 'B', 'C', 'D'] };
const medal = (p) => (p === 100 ? '🏆' : p >= 80 ? '🎉' : p >= 60 ? '👍' : '📚');
const T = {
  en: {
    header: (n) => `🧠 *Quiz* – ${n} questions. Reply with *A*, *B*, *C* or *D* (or type *stop* to end).`,
    qLabel: (i, n) => `*Question ${i}/${n}*`,
    right: '✅ *Correct!*',
    wrong: (l, t) => `❌ *Not quite.* The correct answer was *${l}) ${t}*`,
    final: (s, n, p) => `${medal(p)} *Final score: ${s}/${n}* (${p}%)`,
    again: 'Type *quiz* for a new quiz, or ask me anything about the article.',
    stopped: (s, a) => `⏹ Quiz stopped. Score so far: *${s}/${a}*.`,
    fail: '⚠️ I could not build a quiz this time. Please try again.'
  },
  he: {
    header: (n) => `🧠 *חידון* – ${n} שאלות. השיבו *א*, *ב*, *ג* או *ד* (או כתבו *עצור* לסיום).`,
    qLabel: (i, n) => `*שאלה ${i} מתוך ${n}*`,
    right: '✅ *נכון!*',
    wrong: (l, t) => `❌ *לא בדיוק.* התשובה הנכונה: *${l}) ${t}*`,
    final: (s, n, p) => `${medal(p)} *ציון סופי: ${s} מתוך ${n}* (${p}%)`,
    again: 'כתבו *חידון* לחידון חדש, או שאלו אותי כל דבר על הכתבה.',
    stopped: (s, a) => `⏹ החידון הופסק. הציון עד כה: *${s} מתוך ${a}*.`,
    fail: '⚠️ לא הצלחתי ליצור חידון הפעם. נסו שוב.'
  },
  ru: {
    header: (n) => `🧠 *Викторина* – ${n} вопр. Ответьте *A*, *B*, *C* или *D* (или напишите *стоп*).`,
    qLabel: (i, n) => `*Вопрос ${i}/${n}*`,
    right: '✅ *Верно!*',
    wrong: (l, t) => `❌ *Не совсем.* Правильный ответ: *${l}) ${t}*`,
    final: (s, n, p) => `${medal(p)} *Итог: ${s}/${n}* (${p}%)`,
    again: 'Напишите *викторина* для нового теста или задайте любой вопрос о статье.',
    stopped: (s, a) => `⏹ Викторина остановлена. Счёт: *${s}/${a}*.`,
