const read = (name, prop) => { try { const j = $(name).first().json; return j ? j[prop] : undefined; } catch (e) { return undefined; } };
const parse = (s) => { if (typeof s !== 'string' || !s) return null; try { return JSON.parse(s); } catch (e) { return null; } };

// 1. Atomic duplicate check (Redis INCR): the first delivery sees 1, any re-delivery sees 2+
let dq = {};
try { dq = $('Dedupe Event').first().json || {}; } catch (e) {}
const seen = Number(dq[g.dedupeKey] ?? Object.values(dq).find(v => typeof v === 'number') ?? 1);
if (seen > 1) return [];

// 2. Thread state (one Redis hash per thread: fields art / quiz / hist)
const thread = read('Load Thread', 'thread') || {};
const art = parse(thread.art);
if (!art) return [];                                            // not a summarized-article thread (or expired)
const root = read('Load Map', 'map') || g.lookupTs;             // reaction on the bot's summary message -> thread root
const quizRaw = (typeof thread.quiz === 'string' && thread.quiz) ? thread.quiz : 'null';
const quiz = parse(quizRaw);
const quizActive = !!(quiz && quiz.active);
const history = parse(thread.hist) || [];

const threadKey = `thread:${g.channel}:${root}`;
const base = { slack_channel: g.channel, slack_thread_ts: root, slack_ts: g.ts || '', slack_user: g.user, threadKey };
const title = art.title || (art.meta && art.meta.title) || '';
const mkLog = (type, extra) => ({
  key: 'log:' + new Date().toISOString().slice(0, 7),
  json: JSON.stringify({ type, ts: new Date().toISOString(), url: art.url, title, ...extra })
});
const instantReply = (lang, lines, quizState, log) => [{ json: {
  mode: 'reply', text: render(lang, lines), qLang: lang, ...base,
  threadValue: JSON.stringify({ quiz: quizState ? JSON.stringify(quizState) : quizRaw }),
  logKey: log ? log.key : '', logJson: log ? log.json : ''
} }];

// 3. What does the user want?
const detectLang = (s) => {
