let cur = [], prev = [];
try { cur = $('Load Log This Month').first().json.cur; } catch (e) {}
try { prev = $('Load Log Last Month').first().json.prev; } catch (e) {}

const nowMs = Date.now();
const sinceMs = nowMs - DAYS * 86400000;
const entries = [...parseList(prev), ...parseList(cur)]
  .filter((e) => e.ts && new Date(e.ts).getTime() >= sinceMs)
  .sort((a, b) => new Date(a.ts) - new Date(b.ts));

const uniqBy = (arr, f) => { const seen = new Set(); return arr.filter((x) => { const k = f(x); if (seen.has(k)) return false; seen.add(k); return true; }); };
const articles = uniqBy(entries.filter((e) => e.type === 'summary' && e.status === 'success'), (e) => e.url);
const failed = entries.filter((e) => e.type === 'summary' && e.status === 'error').length;
const quizzes = entries.filter((e) => e.type === 'quiz');
const saved = uniqBy(entries.filter((e) => e.type === 'saved'), (e) => e.url);
if (!articles.length && !quizzes.length && !saved.length) return [];   // quiet week: post nothing

const avg = quizzes.length ? Math.round(quizzes.reduce((s, q) => s + (q.pct || 0), 0) / quizzes.length) : null;
const domainCount = {};
for (const a of articles) if (a.domain) domainCount[a.domain] = (domainCount[a.domain] || 0) + 1;
const topDomains = Object.entries(domainCount).sort((a, b) => b[1] - a[1]).slice(0, 3);

const fmt = (s) => (lang === 'he' ? esc(wrapLatin(String(s))) : esc(String(s)));
const lnk = (url, title) => `<${url}|${fmt(title || url).replace(/\|/g, '¦')}>`;
const d = (ms) => { const x = new Date(ms); return `${x.getDate()}.${x.getMonth() + 1}`; };
const dayName = (iso) => {
  const x = new Date(iso);
  const names = { he: ['א׳', 'ב׳', 'ג׳', 'ד׳', 'ה׳', 'ו׳', 'ש׳'], en: ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'], ru: ['вс', 'пн', 'вт', 'ср', 'чт', 'пт', 'сб'] };
  return names[lang][x.getDay()];
};
const S = {
  en: { head: '📚 *Weekly digest*', read: (n) => `*${n}* articles read`, quizzes: (n, a) => `*${n}* quizzes (avg *${a}%*)`, saved: (n) => `*${n}* saved`, failed: (n) => `⚠️ ${n} links failed`,
        articles: '*Articles*', savedH: '*📌 Saved*', quizH: '*🧠 Quizzes*', top: 'Top sources' },
  he: { head: '📚 *סיכום שבועי*', read: (n) => `נקראו *${n}* כתבות`, quizzes: (n, a) => `*${n}* חידונים (ממוצע *${a}%*)`, saved: (n) => `*${n}* שמורות`, failed: (n) => `⚠️ ${n} קישורים נכשלו`,
        articles: '*כתבות*', savedH: '*📌 שמורות*', quizH: '*🧠 חידונים*', top: 'מקורות מובילים' },
  ru: { head: '📚 *Недельный дайджест*', read: (n) => `прочитано статей: *${n}*`, quizzes: (n, a) => `викторин: *${n}* (средний *${a}%*)`, saved: (n) => `сохранено: *${n}*`, failed: (n) => `⚠️ не удалось: ${n}`,
        articles: '*Статьи*', savedH: '*📌 Сохранённые*', quizH: '*🧠 Викторины*', top: 'Главные источники' }
}[lang];

const stats = [S.read(articles.length)];
if (quizzes.length) stats.push(S.quizzes(quizzes.length, avg));
if (saved.length) stats.push(S.saved(saved.length));
if (failed) stats.push(S.failed(failed));

const lines = [`${S.head} (${d(sinceMs)}–${d(nowMs)})`, stats.join(' · ')];
if (topDomains.length) lines.push(`${S.top}: ` + topDomains.map(([dom, c]) => `${fmt(dom)} (${c})`).join(', '));
if (articles.length) {
  lines.push('', S.articles);
  for (const a of articles.slice(-MAX_ITEMS)) lines.push(`• ${dayName(a.ts)} · ${lnk(a.url, a.title || a.domain)}`);
  if (articles.length > MAX_ITEMS) lines.push(`… +${articles.length - MAX_ITEMS}`);
}
if (saved.length) {
  lines.push('', S.savedH);
  for (const a of saved.slice(-MAX_ITEMS)) lines.push(`• ${lnk(a.url, a.title || a.url)}`);
}
if (quizzes.length) {
  lines.push('', S.quizH);
  for (const q of quizzes.slice(-MAX_ITEMS)) lines.push(`• ${q.score}/${q.total} (${q.pct}%) · ${lnk(q.url, q.title || q.url)}`);
}
const text = lines.map((l) => (lang === 'he' && l ? RLM + l : l)).join('\n');
return [{ json: { text, slack_channel: DIGEST_CHANNEL_ID } }];

// SOLE authority for finalizing a URL's processed state.
// Intake ('Extract URL & Deduplicate') writes a provisional reservation so
// concurrent posts dedupe; this node confirms it on success or deletes it
// on error so failed URLs can be retried.
let url = $json.url || '';
if (!url) {
  try { url = $('Build Prompt').first().json.url || ''; } catch (e) {}
}
const isError = ($json.text || '').startsWith('⚠️');

try {
  const staticData = $getWorkflowStaticData('global');
  if (!staticData.processedUrls) staticData.processedUrls = {};
  if (url) {
    if (isError) delete staticData.processedUrls[url]; // allow retry
    else staticData.processedUrls[url] = Date.now();
  }
} catch (e) {}

return [$input.item];

// Single authoritative language detection — both the direct-extraction
// path and the Jina fallback path route through this node.
const url = $json.url || '';
const text = $json.article || '';

const israeliSites = ['walla.co.il','ynet.co.il','mako.co.il','haaretz.co.il','calcalist.co.il','globes.co.il','maariv.co.il','sport5.co.il','kan.org.il','n12.co.il','reshet13.co.il','ice.co.il','arutz7.co.il','hidabroot.com'];
const russianSites = ['rbc.ru','lenta.ru','ria.ru','tass.ru','kommersant.ru','meduza.io','novayagazeta.ru','iz.ru'];

let language = 'en';
if (israeliSites.some(s => url.includes(s))) language = 'he';
else if (russianSites.some(s => url.includes(s))) language = 'ru';
else {
  const heb = (text.match(/[\u0590-\u05FF]/g) || []).length;
  const cyr = (text.match(/[\u0400-\u04FF]/g) || []).length;
  const total = text.length || 1;
  if (heb / total > 0.08) language = 'he';
  else if (cyr / total > 0.08) language = 'ru';
}

return [{ json: { ...$json, language } }];

const article = $json.article || '';
const language = $json.language || 'en';
const url = $json.url || '';
const slack_channel = $json.slack_channel || '';
const slack_ts = $json.slack_ts || '';
const slack_thread_ts = $json.slack_thread_ts || null;
// FIX: charCount / extractMethod were dropped here, so logs always showed char_count 0
const charCount = $json.charCount || article.length;
const extractMethod = $json.extractMethod || '';
const langNames = { he: 'Hebrew', ru: 'Russian', en: 'English' };
const langName = langNames[language] || 'English';

// Short articles legitimately support fewer bullets; long ones should get 5.
const targetBullets = charCount >= 1500 ? 5 : (charCount >= 800 ? 4 : 3);

const prompt = `Summarize the following article in ${langName}.

OUTPUT FORMAT:
- Output ONLY valid JSON, no markdown fences, no extra text.
- Return a short headline title (5-10 words max) and ${targetBullets === 5 ? 'exactly 5' : 'up to ' + targetBullets} bullet points.
- The title should be a compelling headline capturing the main event or topic.
- Do NOT repeat the title content in the first bullet point.
- The title and all bullets MUST be written in ${langName}.

BULLET QUALITY REQUIREMENTS:
- Each bullet: 3-5 sentences, 60-110 words. Every sentence must contain a DIFFERENT concrete fact.
- A "concrete fact" is: a named person with title/role, specific number/statistic, specific date/timeframe, direct quote, named organization, named location, specific product/technology, specific action, or specific decision.
- Each bullet must cover a DIFFERENT aspect of the story. Zero content overlap between bullets.
- Do NOT invent or guess facts not stated in the article.
- Copy numbers exactly as written in the article (e.g. 5,000 stays 5,000).
- Do NOT include bullet characters (•) inside bullet strings.
- Do NOT include disclaimers like "no further details available".

SUGGESTED STRUCTURE (angles):
1. Core announcement — who, what, when, with specific numbers.
2. Key people — full names, titles, organizations, specific quotes.
3. Technical/operational details — products, systems, figures, dates, locations.
4. Background/context stated in the article — prior events, historical references.
5. Concrete next steps — planned actions, confirmed dates, named successors.

SELF-CHECK before finalizing each bullet:
- Every sentence must contain a NEW named entity, number, date, or quote.
- Remove generic commentary sentences. Do not pad.
- Use all the angles the article actually supports. Return the full requested number of bullets whenever the article has enough distinct facts.

CRITICAL JSON RULE: The "bullets" key must appear EXACTLY ONCE.
Format: {"title": "Headline here", "bullets": ["First...", "Second...", "Third..."]}

Article:
${article}`;

return [{ json: { prompt, language, url, charCount, extractMethod, slack_channel, slack_ts, slack_thread_ts } }];
